#!/bin/sh
# Regenerate the two shipped rubric packs from the committed workbooks.
#
#   ./scripts/build-packs.sh
#
# ONE COMMAND, AND THAT IS THE POINT. The workbooks will be revised (SPEC §11), and a pack that can
# only be regenerated by somebody remembering a pipeline is a pack that stops being regenerated.
# Everything that is not in the workbook — the capability tags, the determinacy tiers, the section
# flags, the pack's identity and the import date — lives in rubrics/maps/, so this script has no
# arguments to get wrong and no date to pass.
#
# RE-RUNNING IT IS BYTE-IDENTICAL. `git diff --stat rubrics/packs` after a run is the check: an
# empty diff means the packs on disk are what the workbooks and the mappings produce today. A
# non-empty one means the instrument or the mapping changed, and the diff is the review.
#
# WHY THIS DOES NOT CALL scripts/dev.sh, WHICH IS OTHERWISE THE DOCUMENTED WAY TO RUN ANYTHING.
# `dev.sh` runs `docker run --rm -t`, and a TTY joins stderr to stdout. The importer deliberately
# writes the pack to stdout and its report to stderr so the command pipes — under `-t` the report
# lands *inside the pack file*, which was observed before this comment was written. So the run is
# done here without a TTY. Same image, same `dev` stage, same dependency set.
#
# POSIX sh, not bash, for the same reason as scripts/dev.sh: this has to work in whatever shell is
# nearest.
#
# Set SIGHTLINE_PYTHON to run against a local interpreter instead of the container.
set -eu

repo_root=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
packs="$repo_root/rubrics/packs"
image=${SIGHTLINE_DEV_IMAGE:-sightline:dev}

mkdir -p "$packs"

if [ -z "${SIGHTLINE_PYTHON:-}" ]; then
    # Build output to stderr, so stdout stays exactly the pack.
    docker build --target dev -t "$image" "$repo_root" >&2
fi

# Each pack is generated by a SEPARATE invocation, and `set -e` stops at the first failure. An
# import that produced no rows exits non-zero, and half-writing the second pack over a failed first
# one would leave the repository in a state nobody chose.
#
# The paths passed in are repository-relative because they are the same inside the image, which
# carries rubrics/ in both stages.
build() {
    workbook="rubrics/source/$1"
    mapping="rubrics/maps/$2"
    out="$3"
    echo "==> $out" >&2
    if [ -n "${SIGHTLINE_PYTHON:-}" ]; then
        (cd "$repo_root" && "$SIGHTLINE_PYTHON" -m sightline.rubric import \
            --workbook "$workbook" --map "$mapping") > "$packs/$out"
    else
        docker run --rm "$image" python -m sightline.rubric import \
            --workbook "$workbook" --map "$mapping" > "$packs/$out"
    fi
}

build "UCCS OSCQR 3.1.3.xlsx"      uccs-oscqr-3-1-3.yaml uccs-oscqr-3-1-3.yaml
build "UCCS OSCQR RSI Review.xlsm" uccs-oscqr-rsi.yaml   uccs-oscqr-rsi.yaml

echo >&2
echo "Wrote $packs. Check 'git diff rubrics/packs' — an empty diff is the expected result." >&2
